  'support.headerTitle': 'Support',
  'support.title': 'Help centre',
  'support.intro':
    'Here you will find answers to what we get asked the most. If your case is not here, write to us: we answer every message.',
  'support.directContact': 'Direct contact',
  'support.responseWindow': '48 working hours',
  'support.responseTime': 'We answer within {plazo} at most. Support is handled in Spanish.',
  'support.writeToSupport': 'Write to support',
  'support.writeToUsAt': 'Write to us at',
  'support.beforeWriting': 'Before writing',
  'support.beforeWritingIntro': 'With these details we can solve it on the first try:',
  'support.include1': 'The email you signed up with.',
  'support.include2': 'What you expected to happen and what happened instead.',
  'support.include3': 'The phone or browser you use.',
  'support.include4': 'A screenshot, if the problem is visible.',
  'support.faq': 'Frequently asked questions',
  'support.documents': 'Documents',
  'support.q1': 'I forgot my password',
  'support.q1a1':
    'On the sign-in screen, tap "Forgot your password?" and enter your email. You will get a link to create a new one.',
  'support.q1a2':
    'If the email does not arrive in a few minutes, check your spam folder. If it still does not show up, write to us and we will restore your access manually.',
  'support.q2': 'How do I delete my account and what gets deleted',
  'support.q2a1':
    'Go to Settings inside the app and choose "Delete account". You will be asked to confirm because the action cannot be undone.',
  'support.q2a2':
    'Your profile and the associated content are deleted: posts, comments, stories and uploaded files. We may keep minimal records if a legal obligation or an ongoing report requires it.',
  'support.q3': 'My story disappeared',
  'support.q3a1':
    'Stories delete themselves 24 hours after being posted. It is not a bug: they work that way on purpose, just like on other platforms.',
  'support.q3a2': 'Wall posts, on the other hand, stay until you delete them.',
  'support.q4': 'I cannot upload a photo or a video',
  'support.q4a1':
    'The most common cause is the permission. The app needs access to your photos or camera: turn it on in your phone Settings → Z → Photos (or Camera). On iPhone the system only asks once, so if you refused back then you have to turn it on there by hand.',
  'support.q4a2':
    'There is also a size limit. If the file goes over it, the app tells you how big it is and how big it can be; with a long video, trim or compress it before uploading.',
  'support.q4a3': 'Stories accept videos of up to 15 seconds.',
  'support.q5': 'How do I report a post or block someone',
  'support.q5a1':
    'Tap the "···" icon on the post and choose "Report post" or "Block". We review every report.',
  'support.q5a2':
    'When you block a person you stop seeing their content and they stop seeing yours. You can undo it from their profile.',
  'support.q5a3':
    'If it is a serious or urgent situation, write to the support email directly and attach a screenshot.',
  'support.q6': 'Are there payments inside the app?',
  'support.q6a1':
    'No. This version is a members app: it does not sell anything and never asks for payment details.',
  'support.q6a2':
    'Access to the learning content is handled outside the app. If you have questions about your membership, write to us.',
  'support.q7': 'What do I need to use Z',
  'support.q7a1':
    'A recent iPhone or Android phone, or any up-to-date browser. An account created with your email address is enough.',
  'support.q7a2':
    'The app is available in Spanish, English and Portuguese; you can change the language in Settings. Some features, like uploading videos, need a stable connection.',

